/** Actual same-format GROUP files remain log floors, never imported META authority or USER replay. */
class RatisRecoveryMetadataTransitionTest {
    @TempDir(factory=RatisDiskTestDirectory.class) Path root;
    final NativeRangeImage.Limits limits=new NativeRangeImage.Limits(4<<20,32<<20,8);
    final class Adapter implements AutoCloseable {
        final RatisRangeStateMachine machine;final RaftStorage storage;final RatisProofQueryService queries=new RatisProofQueryService(RatisProofFixtures.admission());
        Adapter(ReplicatedRangeStore store,DistributedStoragePool pool,RangeDirectory directory,ReplicaDescriptor local,Path path,boolean recover)throws Exception {
            var range=directory.ranges().stream().filter(r->r.groupId().equals(store.ownership().owner().groupId())).findFirst().orElseThrow();var peers=range.replicas().stream().map(r->RaftPeer.newBuilder().setId(r.peerId()).setAddress(r.address()).build()).toList();var group=RaftGroup.valueOf(RaftGroupId.valueOf(range.groupId()),peers);
            machine=new RatisRangeStateMachine(store,group,limits);machine.cdcBinding(directory.clusterId(),directory.databaseId(),range.rangeId());machine.topologyAuthority((header,stage)->{throw new IOException("No authority lookup during floor inventory");},directory,local,pool);machine.proofQueries(queries);
            storage=RaftStorage.newBuilder().setDirectory(path.toFile()).setOption(recover?RaftStorage.StartupOption.RECOVER:RaftStorage.StartupOption.FORMAT).setStorageFreeSpaceMin(SizeInBytes.ONE_MB).build();storage.initialize();var server=mock(RaftServer.class);var division=mock(RaftServer.Division.class);var info=mock(DivisionInfo.class);var cfg=mock(org.apache.ratis.server.RaftConfiguration.class);
            when(server.getId()).thenReturn(RaftPeerId.valueOf(local.peerId()));when(server.getDivision(group.getGroupId())).thenReturn(division);when(division.getStateMachine()).thenReturn(machine);when(division.getInfo()).thenReturn(info);when(division.getRaftConf()).thenReturn(cfg);when(info.isAlive()).thenReturn(true);when(info.getLifeCycleState()).thenReturn(LifeCycle.State.RUNNING);when(cfg.getCurrentPeers()).thenReturn(peers);when(cfg.getCurrentPeers(org.apache.ratis.proto.RaftProtos.RaftPeerRole.FOLLOWER)).thenReturn(peers);when(cfg.getCurrentPeers(org.apache.ratis.proto.RaftProtos.RaftPeerRole.LISTENER)).thenReturn(List.of());when(cfg.getPreviousPeers()).thenReturn(List.of());when(cfg.getPreviousPeers(any())).thenReturn(List.of());when(cfg.getLogEntryIndex()).thenAnswer(call->store.configuration().index());
            try{machine.initialize(server,group.getGroupId(),storage);}catch(Exception failure){try{queries.stop().get(5,java.util.concurrent.TimeUnit.SECONDS);machine.close();machine.awaitNativeReaders(java.time.Duration.ofSeconds(5));storage.close();}catch(Exception cleanup){failure.addSuppressed(cleanup);}throw failure;}
        }
        @Override public void close()throws Exception{queries.stop().get(5,java.util.concurrent.TimeUnit.SECONDS);machine.close();machine.awaitNativeReaders(java.time.Duration.ofSeconds(5));storage.close();}
    }
    @Test void coveredGroupFloorsSurvivePendingMetadataRegistrationColdReopenAndExactInstallIncludingEqualCut()throws Exception {
        for(boolean equal:List.of(false,true))try(var source=new RatisTwoPoolWorkflowFixture(root.resolve("source-"+equal),false)) {
            var directory=source.firstDirectory;var range=directory.ranges().getFirst();var original=root.resolve("original-"+equal+".group");var future=root.resolve("future-"+equal+".group");var sourceStore=source.store(range.groupId());var initial=NativeRangeImage.write(original,sourceStore,limits);source.server.machines.get(RaftGroupId.valueOf(range.groupId())).notifyTermIndexUpdated(1,initial.position().index()+1);var futureManifest=NativeRangeImage.write(future,sourceStore,limits);var split=source.split();var freeze=sourceStore.topologyFreeze();var metadata=root.resolve("incoming-"+equal+".meta");NativeRangeImage.Manifest image;try(var pin=sourceStore.captureMetadataForRecovery()){image=NativeRangeImage.writeMetadataAdmitted(metadata,pin,pin.interval(),limits,NativeRangeImage.IoAdmission.UNLIMITED);}var cfg=sourceStore.configuration();var cut=new RatisCatalogue(source.catalogue,directory.clusterId(),directory.databaseId(),source.plan.catalogue().groupId(),source.plan.catalogue().epoch(),source.plan.catalogue().schemaDigest(),source.plan.catalogue().directoryColumn()).readView(directory.domainId()).cut();var registration=new NativeMetadataRecoveryRegistration(new UUID(999,equal?1:2),source.plan.catalogue().groupId(),cut,directory,freeze,source.local,source.local,cfg.term(),cfg.index(),cfg.data(),image.position(),image.sha256(),Set.of(),null);
            var path=root.resolve("receiver-"+equal);var raft=root.resolve("raft-"+equal);var pools=new RatisTopologyRecoveryAnchorTest();
            try(var pool=pools.pool(path)){
                var store=pool.openRange(new RangeOwnership.Owner(range.groupId(),range.rangeEpoch()),new RangeOwnership.Interval(directory.domainId(),directory.columns(),range.lowerInclusive(),range.upperExclusive()),directory.schemaDigest(),Map.of(source.first.columnIds().iterator().next(),"data"),Set.of());store.fence();store.installSnapshot(original,limits);store.enableLogicalSchema(source.first);
                try(var adapter=new Adapter(store,pool,directory,source.local,raft,false)){
                    assertEquals(initial.position().index(),adapter.machine.takeSnapshot());
                    if(equal){adapter.machine.notifyTermIndexUpdated(1,futureManifest.position().index());RatisMetadataOutcomeReplayTest.replay(adapter.machine,new RatisTopologyFreezeRecord(split,range.groupId(),freeze.admissionDigest()).encode(),freeze.position().index());assertEquals(image.position(),store.applied());assertEquals(image.position().index(),adapter.machine.takeSnapshot());}
                    var floor=adapter.machine.getLatestSnapshot();assertEquals(NativeRangeImage.Kind.GROUP,NativeRangeImage.kind(floor.getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));assertNull(NativeRangeImage.inspect(floor.getFiles().getFirst().getPath(),limits).topologyOrigin());
                    assertThrows(IOException.class,()->adapter.machine.qualifyMetadataRecoveryFloor(wrongDomain(registration)));
                    var bytes=Files.readAllBytes(floor.getFiles().getFirst().getPath());var corrupt=bytes.clone();corrupt[corrupt.length-1]^=1;Files.write(floor.getFiles().getFirst().getPath(),corrupt);try{assertThrows(IOException.class,()->adapter.machine.qualifyMetadataRecoveryFloor(registration));}finally{Files.write(floor.getFiles().getFirst().getPath(),bytes);}
                    if(!equal){var target=adapter.machine.getStateMachineStorage().getSnapshotFile(futureManifest.position().term(),futureManifest.position().index()).toPath();Files.copy(future,target);MD5FileUtil.saveMD5File(target.toFile(),MD5FileUtil.computeMd5ForFile(target.toFile()));var advanced=new SingleFileSnapshotInfo(new FileInfo(target,MD5FileUtil.computeMd5ForFile(target.toFile())),TermIndex.valueOf(futureManifest.position().term(),futureManifest.position().index()));var pointer=RatisRangeStateMachine.class.getDeclaredField("durableSnapshot");pointer.setAccessible(true);pointer.set(adapter.machine,advanced);try{assertThrows(IOException.class,()->adapter.machine.qualifyMetadataRecoveryFloor(registration),"A valid file ahead of actual native A is not a floor");}finally{pointer.set(adapter.machine,floor);Files.delete(target);Files.deleteIfExists(MD5FileUtil.getDigestFileForFile(target.toFile()).toPath());}}
                    var nativeCut=store.applied();adapter.machine.qualifyMetadataRecoveryFloor(registration);adapter.machine.pauseRecoveryRegistration(registration.imageCut());pool.openMetadataRecovery(registration);adapter.machine.resumeRecoveryRegistration();assertEquals(nativeCut,store.applied());assertEquals(floor.getIndex(),adapter.machine.getLatestSnapshot().getIndex());assertMissing(adapter.machine,store);assertStrictInstallRejected(adapter.machine,floor.getFiles().getFirst().getPath(),floor.getTermIndex());
                }
            }
            if(equal)try(var pool=pools.pool(path)){var store=pool.openMetadataRecovery(registration);try(var adapter=new Adapter(store,pool,directory,source.local,raft,true)){
                assertMissing(adapter.machine,store);assertEquals(image.position(),store.applied());adapter.machine.prepareRecoveryReplacement();adapter.machine.pause();
                var canonical=adapter.machine.getStateMachineStorage().getSnapshotFile(image.position().term(),image.position().index()).toPath();Files.copy(metadata,canonical,StandardCopyOption.REPLACE_EXISTING);MD5FileUtil.saveMD5File(canonical.toFile(),MD5FileUtil.computeMd5ForFile(canonical.toFile()));SessionJournalFiles.force(canonical);SessionJournalFiles.force(MD5FileUtil.getDigestFileForFile(canonical.toFile()).toPath());SessionJournalFiles.force(canonical.getParent());
                assertFalse(store.pendingInstallation());assertFalse(store.metadataRecoveryImageInstalled());assertEquals(NativeRangeImage.Kind.METADATA,NativeRangeImage.kind(canonical,NativeRangeImage.IoAdmission.UNLIMITED));
                // Crash boundary: the exact META file is durable, but no native installation began.
            }}
            try(var pool=pools.pool(path)){var store=pool.openMetadataRecovery(registration);try(var adapter=new Adapter(store,pool,directory,source.local,raft,true)){
                if(equal){assertTrue(store.metadataRecoveryImageInstalled(),"Cold inventory must install the exact registered META even when native A already equals its cut");assertTrue(store.metadataRecoveryPending());}
                else {assertMissing(adapter.machine,store);assertTrue(adapter.machine.getLatestSnapshot().getIndex()<=registration.imageCut().index());assertEquals(NativeRangeImage.Kind.GROUP,NativeRangeImage.kind(adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));
                    adapter.machine.prepareRecoveryReplacement();adapter.machine.pause();var stage=Files.createDirectories(field(adapter.machine,"snapshotTmp",Path.class).resolve("snapshot-meta-transition"));var incoming=stage.resolve(adapter.machine.getStateMachineStorage().getSnapshotFile(image.position().term(),image.position().index()).getName());Files.copy(metadata,incoming);MD5FileUtil.saveMD5File(incoming.toFile(),MD5FileUtil.computeMd5ForFile(incoming.toFile()));SessionJournalFiles.force(incoming);SessionJournalFiles.force(MD5FileUtil.getDigestFileForFile(incoming.toFile()).toPath());SessionJournalFiles.force(stage);adapter.machine.reinitialize();}
                assertTrue(store.metadataRecoveryImageInstalled());assertTrue(store.metadataRecoveryPending());assertEquals(NativeRangeImage.Kind.METADATA,NativeRangeImage.kind(adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));store.completeMetadataRecovery(registration,image.position(),store.configuration());adapter.machine.refreshRecoveryEligibility();assertFalse(store.metadataRecoveryPending());assertFalse(store.admissionOpen());
            }}
            {
            NativeMetadataRecoveryRegistration successor;
            try(var pool=pools.pool(path)){var store=pool.openMetadataRecovery(registration);try(var adapter=new Adapter(store,pool,directory,source.local,raft,true)){
                assertFalse(store.metadataRecoveryPending());assertFalse(store.admissionOpen());assertEquals(NativeRangeImage.Kind.METADATA,NativeRangeImage.kind(adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));
                source.server.machines.get(RaftGroupId.valueOf(range.groupId())).notifyTermIndexUpdated(1,sourceStore.applied().index()+1);var laterFile=root.resolve("successor-"+equal+".meta");NativeRangeImage.Manifest later;try(var pin=sourceStore.captureMetadataForRecovery()){later=NativeRangeImage.writeMetadataAdmitted(laterFile,pin,pin.interval(),limits,NativeRangeImage.IoAdmission.UNLIMITED);}var nextCfg=sourceStore.configuration();successor=new NativeMetadataRecoveryRegistration(new UUID(999,equal?21:20),registration.catalogue(),registration.catalogueCut(),directory,freeze,source.local,source.local,nextCfg.term(),nextCfg.index(),nextCfg.data(),later.position(),later.sha256(),registration.mergeColumns(),registration.currentPredecessor());
                var oldCut=store.applied();adapter.machine.qualifyMetadataRecoveryFloor(successor);adapter.machine.pauseRecoveryRegistration(successor.imageCut());pool.openMetadataRecovery(successor);adapter.machine.resumeRecoveryRegistration();assertEquals(oldCut,store.applied());assertEquals(image.position().index(),adapter.machine.getLatestSnapshot().getIndex());assertMissing(adapter.machine,store);
            }}
            try(var pool=pools.pool(path)){var store=pool.openMetadataRecovery(successor);try(var adapter=new Adapter(store,pool,directory,source.local,raft,true)){
                assertMissing(adapter.machine,store);assertEquals(image.position(),store.applied());assertEquals(image.position().index(),adapter.machine.getLatestSnapshot().getIndex());assertEquals(NativeRangeImage.Kind.METADATA,NativeRangeImage.kind(adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));assertStrictInstallRejected(adapter.machine,adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),adapter.machine.getLatestSnapshot().getTermIndex());
                adapter.machine.prepareRecoveryReplacement();adapter.machine.pause();var stage=Files.createDirectories(field(adapter.machine,"snapshotTmp",Path.class).resolve("snapshot-meta-successor"));var incoming=stage.resolve(adapter.machine.getStateMachineStorage().getSnapshotFile(successor.imageCut().term(),successor.imageCut().index()).getName());Files.copy(root.resolve("successor-"+equal+".meta"),incoming);MD5FileUtil.saveMD5File(incoming.toFile(),MD5FileUtil.computeMd5ForFile(incoming.toFile()));SessionJournalFiles.force(incoming);SessionJournalFiles.force(MD5FileUtil.getDigestFileForFile(incoming.toFile()).toPath());SessionJournalFiles.force(stage);adapter.machine.reinitialize();assertTrue(store.metadataRecoveryImageInstalled());assertTrue(store.metadataRecoveryPending());store.completeMetadataRecovery(successor,successor.imageCut(),store.configuration());adapter.machine.refreshRecoveryEligibility();assertFalse(store.metadataRecoveryPending());assertFalse(store.admissionOpen());
            }}
            try(var pool=pools.pool(path)){var store=pool.openMetadataRecovery(successor);try(var adapter=new Adapter(store,pool,directory,source.local,raft,true)){assertTrue(store.metadataRecoveryImageInstalled());assertFalse(store.metadataRecoveryPending());assertFalse(store.admissionOpen());assertEquals(successor.imageCut(),store.applied());assertEquals(NativeRangeImage.Kind.METADATA,NativeRangeImage.kind(adapter.machine.getLatestSnapshot().getFiles().getFirst().getPath(),NativeRangeImage.IoAdmission.UNLIMITED));}}
            }
        }
    }
    private static void assertMissing(RatisRangeStateMachine machine,ReplicatedRangeStore store)throws Exception{assertTrue(store.metadataRecoveryPending());assertFalse(store.metadataRecoveryImageInstalled());assertFalse(store.admissionOpen());assertThrows(IllegalStateException.class,store::capture);assertEquals(org.apache.ratis.server.impl.RecoveryEligibilityStateMachine.Mode.MISSING,machine.recoveryEligibilityGate().snapshot().mode());}
    private static void assertStrictInstallRejected(RatisRangeStateMachine machine,Path file,TermIndex cut)throws Exception{var method=RatisRangeStateMachine.class.getDeclaredMethod("validateImage",Path.class,TermIndex.class);method.setAccessible(true);var rejected=assertThrows(InvocationTargetException.class,()->method.invoke(machine,file,cut));assertInstanceOf(IOException.class,rejected.getCause());}
    private static NativeMetadataRecoveryRegistration wrongDomain(NativeMetadataRecoveryRegistration original){var before=original.sourceDirectory();var other=new UUID(999,10);var source=new RangeDirectory(before.clusterId(),before.databaseId(),other,before.schemaEpoch(),before.schemaDigest(),before.generation(),before.columns(),before.routingPrefixBytes(),before.ranges());var targets=new ArrayList<RangeDescriptor>();var parent=original.range();targets.add(new RangeDescriptor(new UUID(999,11),new UUID(999,12),parent.rangeEpoch(),parent.configurationVersion(),null,new byte[]{64},RangeDescriptor.TopologyState.ACTIVE,parent.replicas()));targets.add(new RangeDescriptor(new UUID(999,13),new UUID(999,14),parent.rangeEpoch(),parent.configurationVersion(),new byte[]{64},null,RangeDescriptor.TopologyState.ACTIVE,parent.replicas()));var target=new RangeDirectory(source.clusterId(),source.databaseId(),other,source.schemaEpoch(),source.schemaDigest(),source.generation()+1,source.columns(),source.routingPrefixBytes(),targets);var changed=new TopologyChange.Definition(new UUID(999,15),source,target);var freeze=new NativeTopologyFreeze(changed.header(),parent.groupId(),original.freeze().position(),original.freeze().boundsDigest(),original.freeze().admissionDigest());return new NativeMetadataRecoveryRegistration(original.transferId(),original.catalogue(),original.catalogueCut(),source,freeze,original.receiver(),original.sourceOwner(),original.configurationTerm(),original.configurationIndex(),original.sourceConfiguration(),original.imageCut(),original.imageHash(),original.mergeColumns(),original.currentPredecessor());}
}
